    const FLAG = (x, top) => `<path d="M${x} 0V${top}" stroke="#5b5b5b" stroke-width="1.4"/><rect x="${x}" y="${top}" width="12" height="8" fill="#fff" stroke="#3b2a20" stroke-width=".8"/><path d="M${x} ${top + 1.6}h12M${x} ${top + 4.8}h12" stroke="#d8322c" stroke-width="1.6"/><rect x="${x}" y="${top}" width="5.5" height="4.6" fill="#1f3f8f"/><circle cx="${x + 2.6}" cy="${top + 2.3}" r="1.1" fill="#f6c84a"/>`;
