const PMK = " (Pemangku)";
/* v67 (owner Q2 ya): the child Sultan himself is "Tuanku Sultan Iskandar (bawah pemangku)" while he is a minor */
const BPK = " (bawah pemangku)";
const stripSuf = x => { if (!x || !x.name) return; let n = x.name; for (const sf of [PMK, BPK]) if (n.endsWith(sf)) n = n.slice(0, -sf.length); if (n !== x.name) { x.name = n; rSync(x); if (S.people && S.people[x.id]) S.people[x.id].name = n } };
