   const sf = x.id === want ? PMK : x.id === kid ? BPK : "";
   const cur = x.name.endsWith(PMK) ? PMK : x.name.endsWith(BPK) ? BPK : "";
   if (sf === cur) continue;
   if (cur) x.name = x.name.slice(0, -cur.length);
