 const FRAMES = [["kayu", "🪵 Kayu"], ["batik", "🌺 Batik"], ["raya", "🌙 Raya"], ["polaroid", "📷 Polaroid"]];
 function photoCompose(frame, cap) {
  try { SNAPNOLBL = true; draw(performance.now()) } catch (e) { } finally { SNAPNOLBL = false }
  const W = cv.width, H = cv.height, pad = Math.round(W * .045), capH = cap ? Math.round(W * .09) : 0, bottom = frame === "polaroid" ? pad * 3 + capH : pad + capH;
  const c = document.createElement("canvas"); c.width = W + pad * 2; c.height = H + pad + bottom;
  const g = c.getContext("2d");
  const bg = { kayu: "#6b4423", batik: "#7a2e3a", raya: "#1f5a3a", polaroid: "#fbf8f1" }[frame] || "#6b4423";
  g.fillStyle = bg; g.fillRect(0, 0, c.width, c.height);
  if (frame === "kayu") { for (let y = 0; y < c.height; y += 6) { g.fillStyle = `rgba(0,0,0,${.05 + .05 * Math.sin(y * .7)})`; g.fillRect(0, y, c.width, 3) } }
  if (frame === "batik") { g.fillStyle = "#e9b949"; for (let x = pad / 2; x < c.width; x += pad) for (const y of [pad / 2, c.height - pad / 2]) { g.beginPath(); for (let k = 0; k < 8; k++) { const t = k / 8 * Math.PI * 2; g.ellipse(x + Math.cos(t) * pad * .18, y + Math.sin(t) * pad * .18, pad * .12, pad * .06, t, 0, 7) } g.fill() } }
  if (frame === "raya") { g.fillStyle = "#e9c46a"; for (const [x, y] of [[pad, pad], [c.width - pad, pad], [pad, c.height - pad], [c.width - pad, c.height - pad]]) { g.save(); g.translate(x, y); g.rotate(Math.PI / 4); g.fillRect(-pad * .32, -pad * .32, pad * .64, pad * .64); g.strokeStyle = "#1f5a3a"; g.lineWidth = 2; g.strokeRect(-pad * .32, -pad * .32, pad * .64, pad * .64); g.restore() } }
  g.drawImage(cv, pad, pad, W, H);
  g.strokeStyle = "rgba(0,0,0,.35)"; g.lineWidth = 2; g.strokeRect(pad, pad, W, H);
  if (cap) { g.fillStyle = frame === "polaroid" ? "#3b2a20" : "#fff8ea"; g.textAlign = "center"; g.textBaseline = "middle"; g.font = `600 ${Math.round(capH * .5)}px 'Segoe Print','Bradley Hand','Comic Sans MS',cursive`; g.fillText(cap, c.width / 2, H + pad + (bottom - (frame === "polaroid" ? pad : 0)) / 2) }
  return c
 }
