  { const fi = finish; finish = function (s2, c2) { const r = fi.apply(this, arguments); try { if (c2 && c2.type === "yard" && c2.act === "laundry") setTimeout(ask, 1800) } catch (e) { fail(e) } return r } }
  /* the clothesline menu: "Ampaian", and fold from the basket */
