  const jiran = prev => { try { const L = (S.nb || []).filter(n => n.status === "neighbour" && nbDef(n.id) && !residentNb().has(n.id)).sort((a, b) => (b.rel || 0) - (a.rel || 0)); if (!L.length) return null; const i = prev ? (L.findIndex(n => n.id === prev) + 1) % L.length : 0; return { id: L[i].id, name: nbDef(L[i].id).name } } catch (e) { return null } };
