   return `<svg viewBox="0 0 100 124" width="${w}" height="${Math.round(w * 1.24)}" aria-hidden="true"><defs><clipPath id="tbj"><path d="M24 24h52v6c10 6 14 16 14 30v42c0 12-8 18-20 18H30c-12 0-20-6-20-18V60c0-14 4-24 14-30z"/></clipPath></defs><path d="M24 24h52v6c10 6 14 16 14 30v42c0 12-8 18-20 18H30c-12 0-20-6-20-18V60c0-14 4-24 14-30z" fill="#e8f3f4"/><g clip-path="url(#tbj)"><rect x="0" y="${y}" width="100" height="${124 - y}" fill="#f6d77e"/>${coins}</g><path d="M24 24h52v6c10 6 14 16 14 30v42c0 12-8 18-20 18H30c-12 0-20-6-20-18V60c0-14 4-24 14-30z" fill="none" stroke="#6b8f94" stroke-width="2.5"/><rect x="20" y="12" width="60" height="13" rx="4" fill="#b5643c" stroke="#7d3f22" stroke-width="2"/><rect x="40" y="15" width="20" height="4" rx="2" fill="#5a2e18"/><path d="M28 40c-4 8-4 30-2 46" stroke="#fff" stroke-width="3" fill="none" opacity=".7" stroke-linecap="round"/>${ic ? `<text x="50" y="76" font-size="28" text-anchor="middle">${ic}</text>` : ""}</svg>`
