   if (!ok) { S.money -= P; sync(); return false }
   dptOut(P); T.n -= P; T.trips++; T.full = dayIdx();
   const names = ppl.map(x => x.name).join(", ");
   for (const x of ppl) try { setEmo(x, "semangat", 6, "bercuti hasil tabung") } catch (e) { }
   S.lp = (S.lp || 0) + 50;
   try { diary(`🧳 Tabung percutian dibuka: ${names} ke ${D.n} hasil berjimat bersama (+50 mata hidup).`) } catch (e) { }
   try { const cap = `Tabung percutian penuh — ${names} ke ${D.n}`; addAlbum("🧳", cap, false); const e = (S.album2 || [])[0]; if (e && e.t === cap) toImg(jar(1, D.e, 100), u => { e.img = u }) } catch (e) { fail(e) }
