  const hm = t => { const m = ((Math.floor(t) % 1440) + 1440) % 1440; return String(Math.floor(m / 60)).padStart(2, "0") + ":" + String(m % 60).padStart(2, "0") };
  const when = t => (Math.floor(t / 1440) > Math.floor(S.t / 1440) ? "esok " : "") + hm(t);
  const dptOut = v => { try { if (HF.dpt && HF.dptSample) { HF.dptSample(); const D = HF.dpt.cur(); D.jum = Math.max(0, (D.jum || 0) - v) } } catch (e) { fail(e) } };
  const sync = () => { try { HF.dptSample && HF.dptSample() } catch (e) { fail(e) } };
