   ["puyu", "Puyu", [15, 20], null, ["cacing"], [.05, .3], "#6d7348", 1, 0, "Kecil tapi liat. Sisiknya keras dan siripnya tajam — pegang elok-elok."],
   ["toman", "Toman", [7, 10], [17, 19.5], ["cacing"], [1.5, 6], "#3f4b3a", .35, 0, "Saudara besar haruan. Garang betul, terutama bila menjaga anak."],
   ["kelah", "Kelah merah", [7, 11], [16, 19], ["pelet"], [1, 5], "#c4654c", .07, 1, "Raja sungai, sisik merah keemasan — jarang sekali dapat! Di sungai, banyak tempat amalkan tangkap dan lepas."]
