   for (const k in Q.xp) if (!fin(Q.xp[k]) || Q.xp[k] < 0) delete Q.xp[k];
   if (!Q.v82) { Q.v82 = 1; for (const k in Q.buku) { if (!fin(Q.buku[k])) delete Q.buku[k]; else { Q.seen[k] = 1; if (!Q.n[k]) Q.n[k] = 1 } } }   /* once, an old book: each fish caught at least once */
