     const fz = b.querySelector("[data-p8f]"); if (fz) { fz.style.left = (50 + G.fx * 45) + "%"; const dir = d > .02 ? 1 : d < -.02 ? -1 : G.dir; if (dir !== G.dir) { G.dir = dir; fz.classList.toggle("r", dir > 0) } }
     const rz = b.querySelector("[data-p8r]"); if (rz) rz.style.left = (50 + G.rx * 45) + "%";
     const tb = b.querySelector("[data-p8t]"); if (tb) { const hot = G.red > RED * .3; if (hot !== !!G.hot) { G.hot = hot; tb.classList.toggle("hot", hot) } }
