   c.querySelectorAll("[data-atb]").forEach(x => x.onclick = () => { const A = atap(); const r = choose(A ? A.g : "panjang", x.dataset.atb); if (r !== true) toast(r); else { BR.lihat = true; try { sfx("coin") } catch (e) { } } try { renderTop() } catch (e) { } renderBuy(); redrawNow() });
