  { const st = BR.setTool; BR.setTool = function (t) { if (t === "atap") BR.lihat = true; return st.apply(this, arguments) } }
  try {
   const gb = GUIDE.find(g2 => g2[0] === "bina");
   if (gb) gb[4].push("<b>🏠 Bumbung:</b> pilih gaya (Panjang, Limas, Rata) dan bahan (Zink, Genting, Atap nipah). Bumbung ditunjuk di atas rumah; ketik rumah untuk lihat ke dalam.")
  } catch (e) { }
