  /* ---- the library (this device only) ---- */
  const lib = () => { try { const a = JSON.parse(lsGet("pelan", "[]")); return Array.isArray(a) ? a.filter(p => p && typeof p === "object" && p.w && typeof p.w === "object") : [] } catch (e) { return [] } };
