   if (PL.tool === "lihat") { say("Pilih alat di bawah (🧱 🚪 🪟 🧽), kemudian ketik garisan pada pelan."); return }
   if (!floorsOn().includes(PL.f)) return;
   const e = edgeAt(ev); PL.hov = e;
   if (!e) { say("Ketik tepat pada garisan antara dua petak."); paint(); return }
   const f = PL.f; let r;
   if (PL.tool === "dinding") r = BR.addWall(f, e);
   else if (PL.tool === "padam") r = BR.eraseEdge(f, e);
   else r = BR.setOpening(f, e, PL.tool === "pintu" ? "p" : "t");
   say(r === true ? "✔ Siap. ↶ Batal di atas rumah boleh membatalkannya." : r);
   if (r === true) { try { sfx("coin") } catch (er) { } try { renderTop() } catch (er) { } }
