 /* the recipe card needs the paintings at once: wait for the kedai sheets (first time only), then open */
 { let wait = false; const KA = HF.kedaiAtlas; HF.k6open = (pd, s2, set) => { if (!KA || KA.ready()) return open6(pd, s2, set); if (wait) return true; wait = true; KA.when(() => { wait = false; try { open6(pd, s2, set) } catch (e) { fail(e) } }); return true } }
