  epal: ["🍎", "Epal", 1.2, [3, 8], [15, 30], null, 1], oren: ["🍊", "Oren", 1, [4, 9], [20, 40], null, 1], durian: ["🟢", "Durian", 12, [1, 3], [4, 8], null, 0]
