 const rel = (id, v) => { try { const x = (S.nb || []).find(n => n && n.id === id); if (x) x.rel = clamp((x.rel || 0) + v, -100, 100) } catch (e) { } };
 const slots = B => 3 + (B.rep >= 25 ? 1 : 0) + (B.rep >= 60 ? 1 : 0);
