  if (S.money < c) { toast(`Duit tak cukup: beli yang kurang ${rm(c)}.`); return false }
  dpt(); S.money -= c; for (const r of p.miss) add(r.f, o.g, r.short); try { sfx("coin") } catch (e) { }
  toast(`🛒 Beli ${p.miss.map(r => `${r.short} ${FR[r.f][1].toLowerCase()}`).join(", ")} (${GR[o.g].toLowerCase()}) = ${rm(c)}. Kini boleh hantar.`);
