  if (!p.ok) { toast(`Stok belum cukup untuk ${o.nm}: kurang ${p.miss.map(r => `${r.short} ${FR[r.f][1].toLowerCase()}`).join(", ")} (mutu ${GR[o.g].toLowerCase()}+).`); return false }
