 const unit = c => c.re ? c.re * 60 / c.n : 1;
 const ripeN = p => { if (!p || !p.m) return 0; const c = CI[p.c]; return c.re ? Math.min(c.cap, Math.floor(p.a / unit(c) + 1e-9)) : c.n };
 const dry = p => day() - p.w;          /* 0 today … */
 const stage = p => !p ? "kosong" : ripeN(p) > 0 ? "masak" : !p.m ? (frac(p) < .35 ? "benih" : "muda") : "besar";
