  const noise = () => { const c = SND.ctx; if (!nbuf) { nbuf = c.createBuffer(1, c.sampleRate, c.sampleRate); const d = nbuf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1 } return nbuf };
  const nz = (t, dur, type, f0, f1, vol, q) => { const c = SND.ctx, s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain(); s.buffer = noise(); s.loop = true; f.type = type; f.frequency.setValueAtTime(f0, t); if (f1) f.frequency.exponentialRampToValueAtTime(f1, t + dur); if (q) f.Q.value = q; g.gain.setValueAtTime(1e-4, t); g.gain.linearRampToValueAtTime(vol, t + .02); g.gain.exponentialRampToValueAtTime(1e-4, t + dur); s.connect(f); f.connect(g); g.connect(SND.fx); s.start(t); s.stop(t + dur + .05) };
  const sweep = (t, f0, f1, dur, vol, type) => { const c = SND.ctx, o = c.createOscillator(), g = c.createGain(); o.type = type || "sine"; o.frequency.setValueAtTime(f0, t); o.frequency.exponentialRampToValueAtTime(f1, t + dur); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(1e-4, t + dur); o.connect(g); g.connect(SND.fx); o.start(t); o.stop(t + dur + .03) };
