   nasi: d => [pour("Basuh beras", "Basuh sampai air jernih.", { btn: "Tahan untuk tuang air", col: "#e9e4d2" }), tap("Perasakan", "Garam sedikit dan daun pandan.", [["🧂", "Garam", 1], ["🌿", "Pandan", 1]]), wait("Masak nasi", "Jangan selalu buka tutup periuk.", 4, "Nasi sedang masak"), stir("Tumis lauk", "Tumis sampai wangi.", "gaul", "#b8742d"), plate(GR.nasi, 2)],
   kuih: d => [tap("Sukat bahan", "Sukat dengan teliti — kuih bergantung pada sukatan.", [["🌾", "Tepung", 3], ["🍬", "Gula", 2], ["🥥", "Santan", 2]]), stir("Gaul adunan", "Gaul sampai licin tanpa ketulan.", "gaul", "#f1dfa4"), pour("Tuang ke acuan", "Isi tiga suku acuan sahaja.", { btn: "Tahan untuk tuang adunan", col: "#f1dfa4" }), wait("Kukus atau bakar", "Jangan buka penutup awal-awal.", 4, "Kuih sedang masak"), plate(GR.kuih, 1)],
   sarapan: d => [tap("Sedia adunan", "Doh yang direhatkan lebih lembut.", [["🌾", "Tepung", 3], ["🥚", "Telur", 1]]), stir("Uli", "Uli sampai licin.", "gaul", "#f0ddb0"), gau("Panaskan tawa", "Tawa panas = hasil berlapis.", { btn: "Tawa dah panas! ✋" }), flip("Masak dan pusing", "Pusing bila perang keemasan.", 2, d.e), plate(GR.lauk, 1)],
