    const place = () => { const f = N ? k / C : 0, l = q(".mkwh.l"), r = q(".mkwh.r"), rs = q(".mkres"); if (!l) return; l.style.transform = `translateX(${-f * 34}px) rotate(${-f * 5}deg)`; r.style.transform = `translateX(${f * 34}px) rotate(${f * 5}deg)`; l.style.opacity = r.style.opacity = String(Math.max(0, 1 - f * 2.2)); rs.style.opacity = f ? "1" : "0"; rs.style.clipPath = `inset(0 ${((1 - f) * 100).toFixed(1)}% 0 0)`; rs.style.transform = `scale(${.9 + .1 * f})` };   /* the parts appear one cut at a time, left to right, while the two halves of the bird slide apart and go */
