   { const [x, y] = W2(TRAY.kuih, MEJA.v); for (let k = 0; k < 6; k++) D.ball(x + ((k % 3) - 1) * .27, y + (Math.floor(k / 3) - .5) * .27, MEJA.z + .1, .12, KL[k % 3]) }
   { const [x, y] = W2(TRAY.teh, MEJA.v); for (let z = 0; z < .6; z += .04) D.ball(x, y, MEJA.z + z + .05, .2 - z * .08, JUG); D.ball(x, y, MEJA.z + .68, .1, lut([240, 240, 236])) }
   { const [x, y] = W2(TIN, MEJA.v + .1); for (let z = 0; z < .3; z += .04) D.ball(x, y, MEJA.z + z + .05, .17, TINL) }
   /* the bag being filled at the left end of the meja */
