   if (got(c) < need(c)) { A.say("Pesanan belum lengkap"); A.snd("tick"); return }
   G.cash = { t: 0 }; M.poseT = .7; M.p2 = "serah"; A.snd("drop"); A.say(`🤝 Serah kepada ${nameOf(c)} — ambil duit RM ${sum(c.o).toFixed(2)}`)
