  { src: "img/pv/bk_kenduri.webp", f0: .22, f1: .5, z0: 1.04, z1: 1.12, y0: -.012, y1: .012, ms: 2900, cap: "…setiap rumah ada cerita, setiap hidangan ada kenangan." },
  { src: "img/pv/bk_tapak.webp", f0: .55, f1: .35, z0: 1.12, z1: 1.04, y0: .01, y1: -.01, ms: 3200, cap: "", title: true }
