  ERR.hf_perabot = { label: "Ke kedai perabot: set gaya & katalog", icon: "🪑", dur: 25, ages: ["teen", "adult", "elder"], eff: { fun: .2 }, place: "perabot", when: OPEN, whenTxt: "9:00–21:00" };
