    for (const c of [...g.children]) { if (c.tagName === "title" || c.hasAttribute("data-o0") || c.classList.contains("hfsu") || (c.tagName === "ellipse" && c.getAttribute("fill") === "none") || (c.tagName === "text" && c.getAttribute("font-size") === "18")) continue; w.appendChild(c) }
