 const R = (x0, y0, x1, y1) => { const a = []; for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) a.push([x, y]); return a };
 const rg = (n, f) => Array.from({ length: n }, (_, i) => f(i));
 /* partitions drawn from the pictures: the stair run (four row slices on the left edge of col 5), the ground bathroom (back and left walls, open to the south), the guest room (back and left walls, door gap at row 10); upper: master bedroom (door gap at row 9), the back room (door gap at row 3), the front room (door gap at row 9), the bathroom's back wall, the stairwell's rail */
 const WALLS0 = sh(["v,5,5", "v,5,6", "v,5,7", "v,5,8", "h,8,5", "h,9,5", "h,10,5", "v,8,5", "v,8,6", "h,8,8", "h,9,8", "h,10,8", "v,8,8", "v,8,9", "v,8,11", "v,8,12"]);
