 /* edges that stop people but are not drawn: the outer walls (in the picture; the front door gap h,5,13 + h,6,13 stays open on the ground floor) */
 const HID0 = sh(rg(10, a => "h," + (a + 1) + ",1").concat(rg(12, b => "v,1," + (b + 1)), rg(12, b => "v,11," + (b + 1)), rg(10, a => a + 1).filter(a => a !== 5 && a !== 6).map(a => "h," + a + ",13")));
